                bid = DAILY_SALARY * 0.85
            else:
                bid = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.55)
        else:
            if my_hp <= 5:
                bid = DAILY_SALARY * 0.7
            else:
                bid = max(highest_prev_bid + 0.5, DAILY_SALARY * 0.4)
    else:
